import com.comsol.model.*;import com.comsol.model.util.*;import java.util.*;
public class BoundaryMap {public static void main(String[] a){try{ModelUtil.initStandalone(false);Model m=ModelUtil.load("M",a[0]);m.result().numerical().create("bm","AvLine");m.result().numerical("bm").set("solnum",new int[]{1});m.result().numerical("bm").set("expr",new String[]{"r/1[um]","z/1[um]"});for(int b=1;b<=7;b++){m.result().numerical("bm").selection().set(b);double[][] d=m.result().numerical("bm").getReal();System.out.println("BOUNDARY "+b+" "+d[0][0]+" "+d[1][0]);}ModelUtil.clear();System.exit(0);}catch(Exception e){e.printStackTrace();System.exit(1);}}}
